CREATE TABLE `activity` (
	`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,
	`type` text NOT NULL,
	`message` text NOT NULL,
	`created_at` integer NOT NULL
);
--> statement-breakpoint
CREATE TABLE `automations` (
	`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,
	`name` text NOT NULL,
	`description` text NOT NULL,
	`enabled` integer DEFAULT true NOT NULL,
	`runs` integer DEFAULT 0 NOT NULL,
	`last_run_at` integer
);
--> statement-breakpoint
CREATE TABLE `businesses` (
	`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,
	`filing_number` text NOT NULL,
	`name` text NOT NULL,
	`industry` text NOT NULL,
	`city` text NOT NULL,
	`county` text NOT NULL,
	`score` integer NOT NULL,
	`opportunity` text NOT NULL,
	`confidence` integer NOT NULL,
	`stage` text NOT NULL,
	`website` text NOT NULL,
	`owner` text NOT NULL,
	`phone` text NOT NULL,
	`signals_json` text NOT NULL,
	`pipeline_status` text DEFAULT 'unclaimed' NOT NULL,
	`origin` text DEFAULT 'official-sunbiz' NOT NULL,
	`brief` text,
	`created_at` integer NOT NULL,
	`updated_at` integer NOT NULL,
	CONSTRAINT "businesses_score_check" CHECK("businesses"."score" BETWEEN 0 AND 100),
	CONSTRAINT "businesses_confidence_check" CHECK("businesses"."confidence" BETWEEN 0 AND 100)
);
--> statement-breakpoint
CREATE UNIQUE INDEX `businesses_filing_number_unique` ON `businesses` (`filing_number`);--> statement-breakpoint
CREATE TABLE `ingestion_runs` (
	`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,
	`status` text NOT NULL,
	`source` text NOT NULL,
	`records_found` integer DEFAULT 0 NOT NULL,
	`records_qualified` integer DEFAULT 0 NOT NULL,
	`started_at` integer NOT NULL,
	`completed_at` integer
);
--> statement-breakpoint
CREATE TABLE `source_health` (
	`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,
	`name` text NOT NULL,
	`status` text NOT NULL,
	`success_rate` integer NOT NULL,
	`last_checked_at` integer NOT NULL,
	CONSTRAINT "source_health_rate_check" CHECK("source_health"."success_rate" BETWEEN 0 AND 100)
);
--> statement-breakpoint
CREATE UNIQUE INDEX `source_health_name_unique` ON `source_health` (`name`);
